    java.time.format.DateTimeFormatter formatter =
        java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")
                                          .withZone(zone);
    String timestamp = formatter.format(instant);
    // Get level, logger name and message
    String level = event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN";
    String loggerName = event.getLoggerName() != null ? event.getLoggerName() : "UNKNOWN";
    String message = event.getMessage() != null ? String.valueOf(event.getMessage()) : "null";
    // Build the formatted string
    StringBuilder sb = new StringBuilder();
    sb.append("[").append(timestamp).append("] ");
    sb.append(level).append(" ");
    sb.append(loggerName).append(" - ");
    sb.append(message);
    return sb.toString();
}

