public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }
    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file is null");
    }
    java.util.ArrayDeque<File> stack = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File current = stack.pop();
        current.deleteOnExit();
        if (current.isDirectory()) {
            File[] children = current.listFiles();
            if (children == null) {
                throw new IOException("Unable to list directory: " + current.getAbsolutePath());
            }
            for (File child : children) {
                stack.push(child);
            }
        }
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }

    // Local class to perform recursive deletion on JVM shutdown
    class Deleter implements Runnable {
        private final File target;

        Deleter(File target) {
            this.target = target;
        }

        @Override
        public void run() {
            deleteRecursively(target);
        }

        private void deleteRecursively(File f) {
            if (f.isDirectory()) {
                File[] children = f.listFiles();
                if (children != null) {
                    for (File child : children) {
                        deleteRecursively(child);
                    }
                }
            }
            // Attempt deletion; ignore the boolean result (errors are logged if needed)
            f.delete();
        }
    }

    Runtime.getRuntime().addShutdownHook(new Thread(new Deleter(file)));
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    // Add a shutdown hook to delete the file or directory when JVM exits
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        try {
            deleteRecursive(file);
        } catch (IOException ignored) {
            // Ignored: deletion failure during exit is not propagated
        }
    }));
}

/**
 * Recursively deletes a file or directory. If the given {@code file} is
 * a directory, all of its contents are deleted first.
 *
 * @param file the file or directory to delete
 * @throws IOException if deletion fails
 */
private static void deleteRecursive(File file) throws IOException {
    if (file == null) {
        return;
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                deleteRecursive(child);
            }
        }
    }
    if (!file.delete()) {
        throw new IOException("Could not delete: " + file);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    java.util.ArrayDeque<File> stack = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File current = stack.pop();
        current.deleteOnExit();
        if (current.isDirectory()) {
            File[] children = current.listFiles();
            if (children == null) {
                throw new IOException("Failed to list contents of directory: " + current);
            }
            for (File child : children) {
                stack.push(child);
            }
        }
    }
}

