    }

    // Create right part vertices
    for (int i = 0; i < rightVertices; i++) {
        @SuppressWarnings("unchecked")
        V vertex = (V) ("V" + i);
        target.addVertex(vertex);
        resultMap.put("v" + i, vertex);
    }

    // Add edges between every pair of vertices from the left and right partitions
    for (int i = 0; i < leftVertices; i++) {
        V u = resultMap.get("u" + i);
