@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Ensure all vertices from resultMap are present in the target graph
    for (V vertex : resultMap.values()) {
        if (!target.containsVertex(vertex)) {
            target.addVertex(vertex);
        }
    }
    // Split the vertices into two arbitrary groups to form a bipartition
    List<V> allVertices = new ArrayList<>(resultMap.values());
    int mid = allVertices.size() / 2;
    List<V> left = allVertices.subList(0, mid);
    List<V> right = allVertices.subList(mid, allVertices.size());
    // Add edges between every vertex in the first group and every vertex in the second group
    for (V u : left) {
        for (V v : right) {
            target.addEdge(u, v);
        }
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Retrieve all vertices currently in the graph
    List<V> vertices = new ArrayList<>(target.vertexSet());
    int n = vertices.size();

    // If there are fewer than two vertices, no edges can be added
    if (n < 2) {
        return;
    }

    // Split the vertex list into two halves, treating them as the two partitions
    int mid = n / 2;

    // Connect every vertex in the first half to every vertex in the second half
    for (int i = 0; i < mid; i++) {
        V v1 = vertices.get(i);
        for (int j = mid; j < n; j++) {
            V v2 = vertices.get(j);
            // Skip adding an edge if one already exists
            if (!target.containsEdge(v1, v2)) {
                target.addEdge(v1, v2);
            }
        }
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Separate vertices into two partitions. Here we simply alternate vertices
    // between left and right sets. If a specific partitioning is required,
    // this logic should be replaced accordingly.
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    int i = 0;
    for (V vertex : resultMap.values()) {
        if (i % 2 == 0) {
            left.add(vertex);
        } else {
            right.add(vertex);
        }
        i++;
    }

    // Ensure all vertices are present in the graph
    for (V v : left) {
        if (!target.containsVertex(v)) {
            target.addVertex(v);
        }
    }
    for (V v : right) {
        if (!target.containsVertex(v)) {
            target.addVertex(v);
        }
    }

    // Add edges so that every vertex in the left partition is connected
    // to every vertex in the right partition (complete bipartite graph)
    for (V vLeft : left) {
        for (V vRight : right) {
            if (!target.containsEdge(vLeft, vRight)) {
                target.addEdge(vLeft, vRight);
            }
        }
    }
}

