public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Determine the serialized size of the message
    int size = schema.getCachedSize(message);
    if (size < 0) {
        // Use the provided buffer to compute the size
        CodedOutputStream tempCos = CodedOutputStream.newInstance(buffer);
        schema.writeTo(message, tempCos);
        size = buffer.getSize();
    }

    // Write the size prefix (varint) to the output stream
    CodedOutputStream cosOut = CodedOutputStream.newInstance(out);
    cosOut.writeRawVarint32(size);

    // Serialize the message itself to the output stream
    schema.writeTo(message, cosOut);
    cosOut.flush();

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    com.google.protobuf.CodedOutputStream cos = com.google.protobuf.CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    schema.writeTo(cos, message, buffer);
    cos.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Write the message into the provided buffer
    schema.writeTo(buffer, message);
    int msgSize = buffer.getSize();

    // Write the message length as a varint to the output stream
    int temp = msgSize;
    while ((temp & 0xFFFFFF80) != 0) {
        out.write((temp & 0x7F) | 0x80);
        temp >>>= 7;
    }
    out.write(temp);

    // Write the serialized message bytes
    byte[] buf = buffer.getBuffer();
    out.write(buf, 0, msgSize);

    // Reset the buffer for potential reuse
    buffer.reset();

    return msgSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Determine the size of the serialized message
    int size = schema.getCachedSize(message);
    if (size < 0) {
        size = schema.computeSize(message);
    }

    // Serialize the message into the provided LinkedBuffer
    buffer.reset();
    com.google.protobuf.CodedOutputStream messageOut = com.google.protobuf.CodedOutputStream.newInstance(buffer);
    schema.writeTo(message, messageOut);
    messageOut.flush();
    int messageSize = buffer.getSize();

    // Write the length prefix as a varint to the OutputStream
    com.google.protobuf.CodedOutputStream lengthOut = com.google.protobuf.CodedOutputStream.newInstance(out);
    lengthOut.writeUInt32NoTag(messageSize);
    lengthOut.flush();

    // Write the actual message bytes to the OutputStream
    buffer.writeTo(out);

    return messageSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getCachedSize(message);
    if (size == 0) {
        size = schema.getSize(message);
    }
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    schema.writeTo(message, cos);
    cos.flush();
    return size;
}

