public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] actualArgs = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[actualArgs.length];
    for (int i = 0; i < actualArgs.length; i++) {
        Type arg = actualArgs[i];
        if (arg instanceof Class) {
            result[i] = (Class<?>) arg;
        } else if (arg instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) arg).getRawType();
            if (raw instanceof Class) {
                result[i] = (Class<?>) raw;
            } else {
                return null;
            }
        } else {
            // Unable to resolve type variable or wildcard
            return null;
        }
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType){
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType paramType = (ParameterizedType) genericType;
    Type raw = paramType.getRawType();
    if (!(raw instanceof Class<?>)) {
        return null;
    }
    Class<?> rawClass = (Class<?>) raw;

    ParameterizedType targetParam = findParameterizedSuper(targetType, rawClass);
    if (targetParam == null) {
        return null;
    }

    TypeVariable<?>[] rawParams = rawClass.getTypeParameters();
    Type[] targetArgs = targetParam.getActualTypeArguments();
    if (rawParams.length != targetArgs.length) {
        return null;
    }

    // Build mapping from the raw type variables to the target's actual types
    java.util.Map<TypeVariable<?>, Type> mapping = new java.util.HashMap<>();
    for (int i = 0; i < rawParams.length; i++) {
        mapping.put(rawParams[i], targetArgs[i]);
    }

    Type[] actualArgs = paramType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[actualArgs.length];
    for (int i = 0; i < actualArgs.length; i++) {
        Type arg = actualArgs[i];
        if (arg instanceof Class<?>) {
            result[i] = (Class<?>) arg;
        } else if (arg instanceof TypeVariable<?>) {
            Type resolved = mapping.get(arg);
            if (resolved instanceof Class<?>) {
                result[i] = (Class<?>) resolved;
            } else {
                return null;
            }
        } else {
            // Unsupported type argument (WildcardType, ParameterizedType, etc.)
            return null;
        }
    }
    return result;
}

private static ParameterizedType findParameterizedSuper(Class<?> cls, Class<?> raw) {
    // Check direct superclass
    Type superType = cls.getGenericSuperclass();
    if (superType instanceof ParameterizedType) {
        ParameterizedType pt = (ParameterizedType) superType;
        if (pt.getRawType() == raw) {
            return pt;
        }
    }

    // Check direct interfaces
    for (Type iface : cls.getGenericInterfaces()) {
        if (iface instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) iface;
            if (pt.getRawType() == raw) {
                return pt;
            }
        }
    }

    // Recurse up the hierarchy
    Class<?> superCls = cls.getSuperclass();
    if (superCls != null) {
        ParameterizedType result = findParameterizedSuper(superCls, raw);
        if (result != null) {
            return result;
        }
    }
    return null;
}

