public void put(LoggingEvent o){
    int nextTail = (tail + 1) % buffer.length;
    if (nextTail == head) {
        // buffer is full – silently drop the event
        return;
    }
    buffer[tail] = o;
    tail = nextTail;
}

public void put(LoggingEvent o) {
    // If the buffer is full, silently drop the event
    if (count == buffer.length) {
        return;
    }
    buffer[head] = o;
    head = (head + 1) % buffer.length;
    count++;
}

public void put(LoggingEvent o) {
    // If the buffer is full, silently drop the event
    if (count == capacity) {
        return;
    }
    // Place the event into the buffer and advance the write position
    buffer[writePos] = o;
    writePos = (writePos + 1) % capacity;
    count++;
}

public void put(LoggingEvent o) {
    if (write == read) {
        // Buffer is full, silently drop the event
        return;
    }
    buffer[write] = o;
    write = (write + 1) % bufferSize;
}

public void put(LoggingEvent o){
    // Attempt to add the event to the buffer; silently drop if the buffer is full
    buffer.offer(o);
}

protected java.util.List<TimeRange> buildTimeRanges(long start,long end){
    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    final long chunkSize = FETCH_DATA_DURATION;
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + chunkSize, end);
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
