static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 1) return timeBucket;
    int year = (int)(timeBucket / 10000);
    int month = (int)((timeBucket / 100) % 100);
    int day = (int)(timeBucket % 100);
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) return timeBucket;
    int year  = (int)(timeBucket / 10000);
    int month = (int)((timeBucket / 100) % 100);
    int day   = (int)(timeBucket % 100);
    int startDay = 1 + ((day - 1) / dayStep) * dayStep;
    return year * 10000L + month * 100L + startDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    long year = timeBucket / 10000L;
    long monthDay = timeBucket % 10000L;
    long month = monthDay / 100L;
    long day = monthDay % 100L;
    long bucketStartDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + bucketStartDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000L;
    long month = (timeBucket / 100L) % 100L;
    long day = timeBucket % 100L;
    long bucketDay = day - ((day - 1L) % dayStep);
    return year * 10000L + month * 100L + bucketDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    // Parse year, month, day from yyyymmdd format
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    // If dayStep is invalid (<=0), return the original timeBucket
    if (dayStep <= 0) {
        return timeBucket;
    }

    // Compute the compressed day of month
    int compressedDay = ((day - 1) / dayStep) * dayStep + 1;

    // Reassemble year, month, and compressedDay into yyyymmdd long format
    return (long) year * 10000 + (long) month * 100 + compressedDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    // Validate input parameters for safety
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException(
                "index = " + index + ", len = " + len + ", str.length() = " + str.length());
    }

    int totalBytes = 0;
    int charsProcessed = 0;
    int i = index;
    final int end = index + len;

    while (i < end) {
        char c1 = str.charAt(i);
        int codePoint;
        int charCount;

        // Check for surrogate pair (code points > U+FFFF)
        if (Character.isHighSurrogate(c1) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            char c2 = str.charAt(i + 1);
            codePoint = Character.toCodePoint(c1, c2);
            charCount = 2;
        } else {
            codePoint = c1;
            charCount = 1;
        }

        // Determine UTF‑8 byte length for the code point
        if (codePoint <= 0x7F) {
            totalBytes += 1;      // 1 byte
        } else if (codePoint <= 0x7FF) {
            totalBytes += 2;      // 2 bytes
        } else if (codePoint <= 0xFFFF) {
            totalBytes += 3;      // 3 bytes
        } else {
            totalBytes += 4;      // 4 bytes
        }

        i += charCount;
        charsProcessed += charCount;
    }

    return totalBytes;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size++;                              // ASCII
            continue;
        }
        if (ch <= 0x7FF) {
            size += 2;                            // U+0080..U+07FF
            continue;
        }
        // ch is a surrogate or > 0x7FF
        if (Character.isHighSurrogate(ch) && i + 1 < end
                && Character.isLowSurrogate(str.charAt(i + 1))) {
            // Valid surrogate pair -> code point > 0xFFFF
            size += 4;
            i++;                                 // skip low surrogate
            continue;
        }
        // Not part of a surrogate pair -> BMP character
        size += 3;
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int end = index + len;
    int i = index;
    int size = 0;
    while (i < end) {
        int cp = Character.codePointAt(str, i);
        i += Character.charCount(cp);
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("str cannot be null");
    }
    if (index < 0 || len < 0 || index > str.length() || index + len > str.length()) {
        throw new IllegalArgumentException("index and len out of bounds");
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        if (ch >= 0xD800 && ch <= 0xDBFF && i + 1 < end) {
            char low = str.charAt(i + 1);
            if (low >= 0xDC00 && low <= 0xDFFF) {
                // Valid surrogate pair → code point U+10000 .. U+10FFFF
                size += 4;
                i += 2;
                continue;
            }
        }
        int cp = ch;
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else {
            size += 3;
        }
        i++;
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int end = index + len;
    if (end > str.length() || index < 0 || len < 0) {
        throw new IndexOutOfBoundsException("Invalid index/length");
    }
    int size = 0;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;
        } else if (ch < 0x800) {
            size += 2;
        } else if (Character.isHighSurrogate(ch) && (i + 1) < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4;
            i += 2;
            continue;
        } else {
            size += 3;
        }
        i++;
    }
    return size;
}

