        }
    }

    int oldLen = this.length;
    int newLen = oldLen + byteLength;

    // Ensure capacity
    if (newLen > this.array.length) {
        int newCap = Math.max(newLen, this.array.length * 2);
        byte[] newArray = new byte[newCap];
        System.arraycopy(this.array, 0, newArray, 0, oldLen);
        this.array = newArray;
