        }
    }

    // Ensure enough space in the byte vector
    int newSize = this.getSize() + byteLength;
    if (newSize > this.capacity()) {
        this.ensureCapacity(newSize);
    }

    // Copy bytes or add null bytes
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            this.data[this.getSize() + i] = 0;
        }
    } else {
