public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    for (int i = 0; i < str.length(); i++) {
        int codePoint = str.charAt(i);
        if (codePoint <= 0x7F) {
            lb.put((byte) codePoint);
        } else if (codePoint <= 0x7FF) {
            lb.put((byte) (0xC0 | (codePoint >> 6)));
            lb.put((byte) (0x80 | (codePoint & 0x3F)));
        } else if ((codePoint & 0xFC00) == 0xD800 && i + 1 < str.length()) {
            int low = str.charAt(i + 1);
            if ((low & 0xFC00) == 0xDC00) {
                int fullCode = 0x10000 + ((codePoint & 0x3FF) << 10) + (low & 0x3FF);
                lb.put((byte) (0xF0 | (fullCode >> 18)));
                lb.put((byte) (0x80 | ((fullCode >> 12) & 0x3F)));
                lb.put((byte) (0x80 | ((fullCode >> 6) & 0x3F)));
                lb.put((byte) (0x80 | (fullCode & 0x3F)));
                i++; // consume low surrogate
                continue;
            }
            // invalid surrogate pair, replace with replacement character 0xFFFD
            lb.put((byte) 0xEF);
            lb.put((byte) 0xBF);
            lb.put((byte) 0xBD);
        } else {
            lb.put((byte) (0xE0 | (codePoint >> 12)));
            lb.put((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
            lb.put((byte) (0x80 | (codePoint & 0x3F)));
        }
    }
    return lb;
}

