        }
        String segmentText = rawSegment;
        if (decode) {
            try {
                segmentText = java.net.URLDecoder.decode(rawSegment,
                        java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (IllegalArgumentException | java.io.UnsupportedEncodingException e) {
