public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return java.util.Collections.emptyList();
    }
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    String[] segs = path.split("/");
    java.util.List<PathSegmentImpl> list = new java.util.ArrayList<>(segs.length);
    for (String seg : segs) {
        String value = seg;
        if (decode) {
            StringBuilder sb = new StringBuilder(seg.length());
            for (int i = 0; i < seg.length(); ) {
                char c = seg.charAt(i);
                if (c == '%' && i + 2 < seg.length()) {
                    try {
                        int dec = Integer.parseInt(seg.substring(i + 1, i + 3), 16);
                        sb.append((char) dec);
                        i += 3;
                    } catch (NumberFormatException e) {
                        sb.append(c);
                        i++;
                    }
                } else {
                    sb.append(c);
                    i++;
                }
            }
            value = sb.toString();
        }
        list.add(new PathSegmentImpl(value));
    }
    return list;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath(); // raw path with percent-encodings
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }

    int start = 0;
    if (rawPath.startsWith("/")) {
        start = 1; // ignore the leading '/' for absolute paths
    }
    int len = rawPath.length();

    for (int i = start; i < len; i++) {
        if (rawPath.charAt(i) == '/') {
            String encoded = rawPath.substring(start, i);
            String decoded = encoded;
            if (decode) {
                try {
                    decoded = java.net.URLDecoder.decode(encoded, java.nio.charset.StandardCharsets.UTF_8.name());
                } catch (Exception e) {
                    // In the unlikely event of an encoding exception, fall back to the encoded string
                    decoded = encoded;
                }
            }
            segments.add(new PathSegmentImpl(decoded, encoded));
            start = i + 1;
        }
    }

    // Handle the last segment (or single segment)
    if (start <= len) {
        String encoded = rawPath.substring(start);
        String decoded = encoded;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(encoded, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                decoded = encoded;
            }
        }
        segments.add(new PathSegmentImpl(decoded, encoded));
    }

    return segments;
}

