public Converter lookup(final Class<?> clazz){
    if (clazz == null) {
        return null;
    }
    Converter conv = registry.get(clazz);
    if (conv != null) {
        return conv;
    }
    Class<?> superCls = clazz.getSuperclass();
    while (superCls != null) {
        conv = registry.get(superCls);
        if (conv != null) {
            return conv;
        }
        superCls = superCls.getSuperclass();
    }
    Set<Class<?>> visited = new HashSet<>();
    Deque<Class<?>> stack = new ArrayDeque<>();
    Collections.addAll(stack, clazz.getInterfaces());
    while (!stack.isEmpty()) {
        Class<?> iface = stack.pop();
        if (!visited.add(iface)) {
            continue;
        }
        conv = registry.get(iface);
        if (conv != null) {
            return conv;
        }
        Collections.addAll(stack, iface.getInterfaces());
    }
    return null;
}

