private void pop(final String descriptor) {
    // Count how many stack slots should be removed based on the descriptor.
    int slots = 0;
    int i = 0;

    // Handle method descriptors: "(argTypes)returnType"
    if (!descriptor.isEmpty() && descriptor.charAt(0) == '(') {
        i++; // skip '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            // Skip array brackets
            while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= descriptor.length()) break;

            char c = descriptor.charAt(i);
            if (c == 'L') {  // object type
                int end = descriptor.indexOf(';', i);
                if (end == -1) break; // malformed descriptor
                i = end + 1;
                slots += 1;
            } else { // primitive type
                i++;
                slots += (c == 'J' || c == 'D') ? 2 : 1;
            }
        }
        // Return type is not popped
    } else { // single type descriptor
        while (i < descriptor.length()) {
            // Skip array brackets
            while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= descriptor.length()) break;

            char c = descriptor.charAt(i);
            if (c == 'L') { // object type
                int end = descriptor.indexOf(';', i);
                if (end == -1) break; // malformed descriptor
                i = end + 1;
                slots += 1;
            } else { // primitive type
                i++;
                slots += (c == 'J' || c == 'D') ? 2 : 1;
            }
        }
    }

    // Decrement the stack pointer by the computed number of slots.
    // The stack pointer field is assumed to be named `sp` in the containing class.
    sp -= slots;
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.length() == 0) {
        return;
    }
    int i = 0;
    final int n = descriptor.length();

    // If descriptor is a method descriptor, pop only the argument types.
    if (descriptor.charAt(0) == '(') {
        i = 1; // skip '('
        while (i < n && descriptor.charAt(i) != ')') {
            i = popOneType(descriptor, i);
        }
        // Skip the return type (if any) – we just ignore it.
        return;
    }

    // Otherwise treat descriptor as a single type.
    popOneType(descriptor, 0);
}

/**
 * Pops the type represented by {@code descriptor} starting at {@code pos}
 * and returns the index right after the parsed type.
 * Handles primitives, object types, arrays, long/double (two slots).
 */
private int popOneType(final String descriptor, int pos) {
    char c = descriptor.charAt(pos);
    switch (c) {
        case 'B':
        case 'C':
        case 'F':
        case 'I':
        case 'S':
        case 'Z':
            outputStack.pop();
            return pos + 1;
        case 'J':
        case 'D':
            // Long and double occupy two slots
            outputStack.pop();
            outputStack.pop();
            return pos + 1;
        case 'V':
            // Void – nothing to pop
            return pos + 1;
        case 'L':
            // Reference type: consume until ';'
            int semicolon = descriptor.indexOf(';', pos + 1);
            if (semicolon == -1) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            outputStack.pop();
            return semicolon + 1;
        case '[':
            // Array type: skip all leading '['
            int arrayPos = pos + 1;
            while (descriptor.charAt(arrayPos) == '[') {
                arrayPos++;
            }
            // If component type is an object, skip until ';'
            if (descriptor.charAt(arrayPos) == 'L') {
                int end = descriptor.indexOf(';', arrayPos + 1);
                if (end == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                arrayPos = end + 1;
            } else {
                // Primitive component type
                arrayPos += 1;
            }
            outputStack.pop();
            return arrayPos;
        default:
            throw new IllegalArgumentException("Unknown type char '" + c + "' in descriptor: " + descriptor);
    }
}

private void pop(final String descriptor){
    // Empty descriptor: nothing to pop
    if (descriptor == null || descriptor.length() == 0) {
        return;
    }
    if (descriptor.startsWith("(")) {
        int end = descriptor.indexOf(')');
        if (end < 0) {
            throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
        }
        int i = 1; // after '('
        while (i < end) {
            // skip array brackets
            while (i < end && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= end) break;
            char c = descriptor.charAt(i);
            int size = 1;
            if (c == 'J' || c == 'D') {
                size = 2;
                i++; // move past base type
            } else if (c == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon < 0) {
                    throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
                }
                i = semicolon + 1;
            } else {
                // primitive single char
                i++;
            }
            // pop the stack entries for this argument type
            for (int s = 0; s < size; s++) {
                outputStack.removeLast();
            }
        }
    } else {
        // Type descriptor
        int i = 0;
        // skip array brackets
        while (i < descriptor.length() && descriptor.charAt(i) == '[') {
            i++;
        }
        if (i >= descriptor.length()) {
            return; // nothing to pop
        }
        char c = descriptor.charAt(i);
        int size = 1;
        if (c == 'V') {
            size = 0; // void, no stack effect
        } else if (c == 'J' || c == 'D') {
            size = 2;
            i++;
        } else if (c == 'L') {
            int semicolon = descriptor.indexOf(';', i);
            if (semicolon < 0) {
                throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
            }
            i = semicolon + 1;
        } else {
            // primitive single char
            i++;
        }
        for (int s = 0; s < size; s++) {
            outputStack.removeLast();
        }
    }
}

private void pop(final String descriptor) {
    int i = 0;
    if (descriptor.charAt(i) == '(') {
        // Method descriptor: pop all argument types
        i = 1;
        while (descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == '[') {
                // Skip all '[' that denote array dimensions
                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                if (descriptor.charAt(i) == 'L') {
                    // Object array
                    i++; // skip 'L'
                    while (descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++; // skip ';'
                } else {
                    // Primitive array
                    i++; // skip single primitive descriptor
                }
                // Arrays occupy a single stack slot
                output.pop();
            } else if (c == 'L') {
                // Object type
                i++; // skip 'L'
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
                i++; // skip ';'
                output.pop();
            } else {
                // Primitive type
                if (c == 'J' || c == 'D') {
                    output.pop(); // high word
                    output.pop(); // low word
                } else {
                    output.pop();
                }
                i++; // move to next type descriptor
            }
        }
    } else {
        // Single type descriptor: pop it
        char c = descriptor.charAt(i);
        if (c == '[') {
            // Primitive or object array
            while (descriptor.charAt(i) == '[') {
                i++;
            }
            if (descriptor.charAt(i) == 'L') {
                i++; // skip 'L'
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
                i++; // skip ';'
            } else {
                i++; // skip primitive descriptor
            }
            output.pop();
        } else if (c == 'L') {
            // Object type
            i++; // skip 'L'
            while (descriptor.charAt(i) != ';') {
                i++;
            }
            i++; // skip ';'
            output.pop();
        } else {
            // Primitive type
            if (c == 'J' || c == 'D') {
                output.pop();
                output.pop();
            } else {
                output.pop();
            }
        }
    }
}

