    if (size <= 0) {
        return;
    }
    int oldLen = vector.length;
    int newLen = oldLen + size;
    // guard against integer overflow
    if (newLen < 0) {
        throw new OutOfMemoryError("Unable to enlarge byte vector");
    }
    byte[] newVector = new byte[newLen];
    System.arraycopy(vector, 0, newVector, 0, oldLen);
    vector = newVector;
}

private void enlarge(final int size){
    // Calculate the space currently available
    int available = buf.length - pos;
    // If the requested size fits, nothing to do
    if (size <= available) {
        return;
    }
    // Determine the new required capacity
    int required = pos + size;
    // Grow the buffer (double the size each time or just enough)
    int newCapacity = buf.length << 1;
    if (newCapacity < required) {
        newCapacity = required;
    }
    // Allocate a new buffer and copy old contents
    byte[] newBuf = new byte[newCapacity];
    System.arraycopy(buf, 0, newBuf, 0, pos);
    // Replace the old buffer
    buf = newBuf;
}

