        return name;
    }
    char[] chars = name.toCharArray();
    chars[0] = Character.toUpperCase(chars[0]);
    return new String(chars);
}

public static String capitalize(String name) {
    if (name == null || name.isEmpty()) {
        return name;
    }
    // Mimic the reverse of Introspector.decapitalize: preserve strings with initialisms
    if (name.length() > 1 && Character.isUpperCase(name.charAt(0))
            && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    char[] chars = name.toCharArray();
    chars[0] = Character.toUpperCase(chars[0]);
    return new String(chars);
}

public static String capitalize(String name) {
    if (name == null || name.isEmpty()) {
        return name;
    }
    char firstChar = name.charAt(0);
    if (Character.isUpperCase(firstChar)) {
        if (name.length() > 1 && Character.isUpperCase(name.charAt(1))) {
            // Already in the form where the first two characters are uppercase (e.g., "URL");
            // Returning as-is preserves the original capitalization.
            return name;
        }
    }
    // In all other cases, ensure the first character is uppercase
    return Character.toUpperCase(firstChar) + name.substring(1);
}

public static String capitalize(String name){
    if (name == null || name.isEmpty()) {
        return name;
    }
    if (name.length() > 1) {
        char first = name.charAt(0);
        char second = name.charAt(1);
        if (Character.isUpperCase(first) && Character.isUpperCase(second)) {
            // Decapitalize would not change a string whose first two
            // characters are already uppercase, so keep it as is.
            return name;
        }
    }
    // Capitalize the first character
    char first = name.charAt(0);
    char upperFirst = Character.toUpperCase(first);
    if (upperFirst == first) {
        return name;
    }
    return upperFirst + name.substring(1);
}

