    while (current != null) {
        // Here we assume the LinkedBuffer structure contains the following fields:
        //   - byte[] data: the underlying byte array
        //   - int size: the number of valid bytes in this node
        //   - LinkedBuffer next: reference to the next node in the chain
        if (current.size > 0) {
            out.write(current.data, 0, current.size);
            totalSize += current.size;
        }
        current = current.next;
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = 0;
    for (LinkedBuffer cur = node; cur != null; cur = cur.next) {
        int writeLen = cur.buf.length - cur.position;  // bytes written in this node
        out.write(cur.buf, 0, writeLen);
        total += writeLen;
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    if (node == null) {
        return totalSize;
    }
    for (LinkedBuffer current = node; current != null; current = current.next) {
        int length = current.pos;
        if (length > 0) {
            out.write(current.buffer, 0, length);
            totalSize += length;
        }
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        // node.pos represents the number of bytes written into this buffer
        int len = node.pos;
        // Write the bytes from the beginning of the buffer up to len
        out.write(node.buf, 0, len);
        totalSize += len;
        node = node.next;
    }
    return totalSize;
}

