public String format(final LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        // Level
        String level = "";
        try {
            if (event.getLevel() != null) {
                level = event.getLevel().toString();
            }
        } catch (Exception e) {
            level = "UNKNOWN";
        }
        // Logger name
        String logger = "";
        try {
            logger = event.getLoggerName() != null ? event.getLoggerName() : "UNKNOWN";
        } catch (Exception e) {
            logger = "UNKNOWN";
        }
        // Thread name
        String thread = "";
        try {
            thread = event.getThreadName() != null ? event.getThreadName() : "UNKNOWN";
        } catch (Exception e) {
            thread = "UNKNOWN";
        }
        // Message
        String message = "";
        try {
            // Prefer rendered message if available
            if (event.getRenderedMessage() != null) {
                message = event.getRenderedMessage();
            } else if (event.getMessage() != null) {
                message = event.getMessage().toString();
            }
        } catch (Exception e) {
            message = "";
        }
        // Timestamp
        String tsString = "";
        try {
            long ts = event.getTimeStamp();
            java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
            tsString = sdf.format(new java.util.Date(ts));
        } catch (Exception e) {
            tsString = "1970-01-01 00:00:00.000";
        }
        // Construct format: [timestamp] [level] [thread] [logger] - message
        return "[" + tsString + "] [" + level + "] [" + thread + "] [" + logger + "] - " + message;
    } catch (Exception e) {
        // Fallback in case of unexpected error
        return "";
    }
}

