private void putAbstractTypes(final int start, final int end){
    for (int i = start; i < end; ++i){
        final int typeInfo = currentFrame[i];
        final int tag = typeInfo & 0xFF;
        stackMapTableEntries.putByte(tag);
        if (tag > 6){ // OBJECT or UNINITIALIZED
            stackMapTableEntries.putShort((short)(typeInfo >>> 8));
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        // Retrieve the verification type information for this frame entry
        VerificationTypeInfo info = currentFrame[i];

        // The tag specifies the kind of type (TOP, Integer, Float, etc.)
        int tag = info.getTag();
        stackMapTableEntries.putByte((byte) tag);

        // For OBJECT (tag 7) and UNINITIALIZED (tag 8) we need to write an
        // additional u2 field (cp_info index or offset respectively).
        if (tag == 7 || tag == 8) {
            int extra = info.getExtra();          // cp_info index or offset
            stackMapTableEntries.putShort((short) extra);
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        Item item = currentFrame[i];
        switch (item.getTag()) {
            case ITEM_INTEGER:
            case ITEM_FLOAT:
            case ITEM_DOUBLE:
            case ITEM_LONG:
            case ITEM_NULL:
            case ITEM_UNINITIALIZED_THIS:
                stackMapTableEntries.putUnsignedByte(item.getTag());
                break;
            case ITEM_OBJECT:
                stackMapTableEntries.putUnsignedByte(item.getTag());
                stackMapTableEntries.putUnsignedShort(item.getCpoolIndex());
                break;
            case ITEM_UNINITIALIZED:
                stackMapTableEntries.putUnsignedByte(item.getTag());
                stackMapTableEntries.putUnsignedShort(item.getOffset());
                break;
            default:
                throw new IllegalStateException("Unknown verification type tag: " + item.getTag());
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; ++i) {
        AbstractType type = currentFrame[i];
        type.putVerification(stackMapTableEntries, i);
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        // Retrieve the abstract type descriptor from the current frame.
        Object descriptor = currentFrame[i];

        // Convert the descriptor into a verification_type_info structure.
        VerificationTypeInfo vtInfo = convertToVerificationTypeInfo(descriptor);

        // Append the resulting structure to the stackMapTableEntries list.
        stackMapTableEntries.add(vtInfo);
    }
}

