    // Read all bytes from the supplied InputStream into a temporary buffer
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    byte[] tmp = new byte[8192];
    int n;
    while ((n = in.read(tmp)) != -1) {
        baos.write(tmp, 0, n);
    }
    byte[] data = baos.toByteArray();

    // Store the read data in the internal buffer and reset the read pointer
    this.buffer = data;
    this.ptr = 0;
}

