@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    // Ensure the target is java.lang.Character (or primitive char)
    if (char.class != type && Character.class != type) {
        throw new Exception("Can only convert to java.lang.Character type");
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() != 1) {
            throw new Exception("Cannot convert string of length " + cs.length() + " to Character");
        }
        return cs.charAt(0);
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }
    throw new Exception("Cannot convert from " + value.getClass().getName() + " to Character");
}

@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    if (type != Character.class && type != char.class) {
        return null;
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    }
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 0) {
            throw new IllegalArgumentException("Unable to convert empty CharSequence to Character");
        }
        return cs.charAt(0);
    }
    throw new IllegalArgumentException(
            "Cannot convert type " + value.getClass().getName() + " to Character");
}

@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (Character.class.isAssignableFrom(type)) {
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String s = (String) value;
            if (s.length() == 1) {
                return Character.valueOf(s.charAt(0));
            }
            throw new IllegalArgumentException("Cannot convert string to Character: length must be 1");
        }
        if (value instanceof Number) {
            return Character.valueOf((char) ((Number) value).intValue());
        }
    }
    throw new IllegalArgumentException("Cannot convert value of type " + value.getClass() + " to Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Null values are passed through unchanged
    if (value == null) {
        return null;
    }

    // Only handle conversion to Character or char
    if (type == Character.class || type == char.class) {
        // Already a Character
        if (value instanceof Character) {
            return value;
        }
        // String of length 1
        if (value instanceof String) {
            String s = (String) value;
            if (s.length() == 1) {
                return s.charAt(0);
            }
            throw new Exception("Cannot convert String to Character: length != 1");
        }
        // Number (e.g., Integer, Long) -> char code
        if (value instanceof Number) {
            int intVal = ((Number) value).intValue();
            if (intVal >= Character.MIN_VALUE && intVal <= Character.MAX_VALUE) {
                return (char) intVal;
            } else {
                throw new Exception("Integer value out of Character range");
            }
        }
        // General CharSequence (e.g., StringBuilder)
        if (value instanceof CharSequence) {
            CharSequence cs = (CharSequence) value;
            if (cs.length() == 1) {
                return cs.charAt(0);
            }
            throw new Exception("Cannot convert CharSequence to Character: length != 1");
        }
    }

    throw new Exception("Cannot convert type " + value.getClass().getName() + " to Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    // Only perform conversion when the target type is Character or char
    if (!Character.class.isAssignableFrom(type) && type != char.class) {
        return value;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() != 1) {
            throw new IllegalArgumentException("Cannot convert String of length " + s.length() + " to Character");
        }
        return s.charAt(0);
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < 0 || intVal > 0xFFFF) {
            throw new IllegalArgumentException("Numeric value " + intVal + " is out of char range");
        }
        return (char) intVal;
    }
    // Fallback: try to convert via toString()
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }
    throw new IllegalArgumentException("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

