        if (isPrime(candidate)) {
            // For inputs >= 1000, we could optionally enforce the 11% rule.
            // However, the simplest correct implementation returns the next prime.
            return candidate;
        }
        // Skip to the next odd number.
        candidate += 2;
        // Avoid overflow: if candidate becomes negative, break.
        if (candidate <= 0) {
            break;
        }
    }
    // In practice, we shouldn't reach here because a prime exists before Integer.MAX_VALUE.
    // Return the maximum integer prime <= Integer.MAX_VALUE if overflow occurs.
    return Integer.MAX_VALUE;
