@Override public String readString() throws IOException {
    // Expect a 4‑byte big‑endian length prefix followed by UTF‑8 encoded bytes.
    int b1 = in.read();
    if (b1 == -1) throw new java.io.EOFException("Unable to read string length: EOF reached");
    int b2 = in.read();
    if (b2 == -1) throw new java.io.EOFException("Unable to read string length: EOF reached");
    int b3 = in.read();
    if (b3 == -1) throw new java.io.EOFException("Unable to read string length: EOF reached");
    int b4 = in.read();
    if (b4 == -1) throw new java.io.EOFException("Unable to read string length: EOF reached");
    int length = ((b1 & 0xFF) << 24) | ((b2 & 0xFF) << 16) | ((b3 & 0xFF) << 8) | (b4 & 0xFF);
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }
    byte[] buffer = new byte[length];
    int totalRead = 0;
    while (totalRead < length) {
        int bytesRead = in.read(buffer, totalRead, length - totalRead);
        if (bytesRead == -1) {
            throw new java.io.EOFException("Unexpected end of stream while reading string");
        }
        totalRead += bytesRead;
    }
    return new String(buffer, 0, length, java.nio.charset.StandardCharsets.UTF_8);
}

