public final byte[] toByteArray() {
    // Calculate total length of all byte arrays in the buffer collection.
    int totalLength = 0;
    for (byte[] buf : buffers) {
        if (buf != null) {
            totalLength += buf.length;
        }
    }

    // Allocate a single byte array large enough to hold all content.
    byte[] combined = new byte[totalLength];

    // Copy each buffer into the combined array sequentially.
    int position = 0;
    for (byte[] buf : buffers) {
        if (buf != null && buf.length > 0) {
            System.arraycopy(buf, 0, combined, position, buf.length);
            position += buf.length;
        }
    }

    return combined;
}

public final byte[] toByteArray(){
    // Determine total size of all buffers
    int totalSize = 0;
    for (java.nio.ByteBuffer buf : buffers) {
        totalSize += buf.remaining();
    }
    // Copy all buffer contents into a single byte array
    byte[] result = new byte[totalSize];
    int offset = 0;
    for (java.nio.ByteBuffer buf : buffers) {
        // Duplicate to avoid modifying the original buffer's position
        java.nio.ByteBuffer duplicate = buf.duplicate();
        duplicate.flip(); // Prepare for reading
        duplicate.get(result, offset, duplicate.remaining());
        offset += duplicate.remaining();
    }
    return result;
}

