protected int removeUnusedNodes(){
    int removed = 0;
    Iterator<Map.Entry<Integer, Category>> it = categories.entrySet().iterator();
    while(it.hasNext()){
        Map.Entry<Integer, Category> entry = it.next();
        Category node = entry.getValue();
        if (!node.isActive()){
            it.remove();
            removed++;
        }
    }
    return removed;
}

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    return removeUnusedNodesRecursive(root, null);
}

private int removeUnusedNodesRecursive(Category node, Category parent) {
    int removed = 0;
    if (node == null) {
        return 0;
    }
    // Work on a copy of the child list to avoid concurrent modification issues.
    List<Category> children = new ArrayList<>(node.getSubcategories());
    for (Category child : children) {
        removed += removeUnusedNodesRecursive(child, node);
    }
    if (!node.isActive()) {
        if (parent != null) {
            parent.getSubcategories().remove(node);
        } else {
            // Removing the root node
            root = null;
        }
        removed++;
    }
    return removed;
}

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    return removeInactiveRecursive(root);
}

private int removeInactiveRecursive(Category current) {
    int removedCount = 0;
    // Use an iterator to safely modify the list while iterating
    for (Iterator<Category> it = current.getChildren().iterator(); it.hasNext();) {
        Category child = it.next();
        if (!child.isActive()) {
            it.remove();
            removedCount++;
        } else {
            removedCount += removeInactiveRecursive(child);
        }
    }
    return removedCount;
}

protected int removeUnusedNodes() {
    int removedCount = 0;
    if (children == null) {
        return 0;
    }
    java.util.Iterator<Category> it = children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (!child.isActive()) {
            it.remove();
            removedCount++;
        } else {
            // recursively remove from the child's subtree
            removedCount += child.removeUnusedNodes();
        }
    }
    return removedCount;
}

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    return removeUnusedNodesRecursive(root);
}

private int removeUnusedNodesRecursive(Category node) {
    int removed = 0;
    for (int i = 0; i < node.children.size(); i++) {
        Category child = node.children.get(i);
        removed += removeUnusedNodesRecursive(child);
        if (!child.active) {
            node.children.remove(i);
            i--;
            removed++;
        }
    }
    return removed;
}

