private static char decodeHexNibble(final char c){
    char result = Character.MAX_VALUE;
    if (c >= '0' && c <= '9') {
        result = (char)(c - '0');
    } else if (c >= 'a' && c <= 'f') {
        result = (char)(c - 'a' + 10);
    } else if (c >= 'A' && c <= 'F') {
        result = (char)(c - 'A' + 10);
    }
    return result;
}

