private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    while (!circ.current().equals(stop) && !predicate.test(circ.current())) {
        circ.next(dir);
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Start the circulator at the given start node
    OuterFaceCirculator circ = new OuterFaceCirculator(start);

    // We need at least to examine the start node itself
    while (true) {
        Node current = circ.node();

        // If we hit the stop node or a node that satisfies the predicate, we are done
        if (current == stop || predicate.test(current)) {
            return circ;
        }

        // Advance in the requested direction
        circ = (dir > 0) ? circ.next() : circ.prev();

        // If we have circled back to the starting node we stop to avoid an infinite loop
        if (circ.node() == start) {
            // If the start itself is the stop node we should return it
            return start == stop ? circ : null;
        }
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);
    while (true) {
        Node current = circulator.node();
        if (predicate.test(current) || current.equals(stop)) {
            return circulator;
        }
        if (dir > 0) {
            circulator.next();
        } else {
            circulator.prev();
        }
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator positioned at the start node
    OuterFaceCirculator circ = new OuterFaceCirculator(start);

    // Traverse the outer face until we reach the stop node
    while (true) {
        // If the current node satisfies the predicate, return the circulator
        if (predicate.test(circ.node())) {
            return circ;
        }

        // If we have arrived at the stop node, return the circulator to it
        if (circ.node().equals(stop)) {
            return circ;
        }

        // Advance in the specified direction (positive for next, negative for previous)
        circ = dir > 0 ? circ.next() : circ.prev();
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null) {
        return new OuterFaceCirculator(stop);
    }
    Node current = start;
    if (predicate.test(current)) {
        return new OuterFaceCirculator(current);
    }
    while (!current.equals(stop)) {
        current = dir > 0 ? current.getOuterNext() : current.getOuterPrev();
        if (current == null) {
            break;
        }
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
    }
    return new OuterFaceCirculator(stop);
}

