    while (ptr >= len) {
        len = in.read(buffer);
        if (len <= 0) {
            throw new EOFException("No more data available");
        }
        ptr = 0; // reset position to the start of the new data chunk
    }
    // Return the next byte and advance the pointer.
    return buffer[ptr++];
}

public byte readByte() throws IOException {
    if (pos >= limit) {
        limit = in.read(buffer);
        pos = 0;
        if (limit <= 0) {
            throw new IOException("No more data");
        }
    }
    return buffer[pos++];
}

public byte readByte() throws IOException {
    if (bufPos >= bufLen) {
        bufLen = in.read(buffer);
        if (bufLen == -1) {
            throw new EOFException("End of stream");
        }
        bufPos = 0;
    }
    return buffer[bufPos++];
}

public byte readByte() throws IOException {
    if (bufferPos >= bufferLimit) {
        bufferLimit = in.read(buffer);
        if (bufferLimit == -1) {
            throw new IOException("End of stream");
        }
        bufferPos = 0;
    }
    return buffer[bufferPos++];
}

@Override public Action inspect(AtmosphereResource r){
    if (r == null) {
        return Action.CONTINUE;
    }
    try {
        // If a Transport is defined and it is not a WebSocket, suspend the resource
        Object transportObj = r.getTransport();
        if (transportObj != null && !transportObj.toString().equalsIgnoreCase("websocket")) {
            if (!r.isSuspended()) {
                r.suspend();
            }
        }
    } catch (NoSuchMethodError | java.lang.Exception ignored) {
        // Fallback: if the API does not provide getTransport(), simply suspend
        if (!r.isSuspended()) {
            r.suspend();
        }
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r) {
    if (r == null) {
        return Action.CONTINUE;
    }
    AtmosphereResource.TRANSPORT transport = r.getTransport();
    // Auto‑suspend for all transports except WebSocket
    if (transport != null
            && transport != AtmosphereResource.TRANSPORT.WEBSOCKET
            && !r.isSuspended()) {
        r.suspend();
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    String transport = r.getTransport();
    if (transport != null && !transport.equalsIgnoreCase("websocket")) {
        // Automatically suspend for any non‑websocket transport
        try {
            r.suspend();
        } catch (Exception e) {
            // ignore suspension failures
        }
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    // Automatically suspend the resource if it is a suspendable transport
    try {
        // Suspend the resource so that the transport can keep the connection alive
        r.suspend();
    } catch (Exception e) {
        // Log or ignore if suspend fails – the inspector should not disrupt flow
    }
    return Action.CONTINUE;
}

