public int appendLoopOnAppenders(LoggingEvent event){
    int count = 0;
    if(event == null){
        return count;
    }
    Iterator appenders = null;
    try{
        appenders = this.getAllAppenders();
    }catch(Throwable t){
        // ignore
    }
    if(appenders == null){
        return count;
    }
    while(appenders.hasNext()){
        Object obj = appenders.next();
        if(!(obj instanceof Appender)){
            continue;
        }
        try{
            ((Appender)obj).doAppend(event);
            count++;
        }catch(Throwable t){
            // ignore errors from individual appenders
        }
    }
    return count;
}

