protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if(tour == null || tour.isEmpty() || graph == null){
        return null;
    }

    // Build adjacency map for the edges in the tour
    Map<V, List<E>> adjacency = new HashMap<>();
    for(E e : tour){
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
    }

    // Pick an arbitrary start edge
    E startEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(startEdge);
    V currentVertex = graph.getEdgeTarget(startEdge);

    List<V> vertexList = new ArrayList<>();
    List<E> edgeList   = new ArrayList<>();
    Set<E> usedEdges   = new HashSet<>();

    // Initialize path
    vertexList.add(startVertex);
    edgeList.add(startEdge);
    usedEdges.add(startEdge);
    vertexList.add(currentVertex);

    // Build the tour by walking around the cycle
    while(true){
        // If we returned to the start vertex after using all edges, tour is complete
        if(currentVertex.equals(startVertex) && usedEdges.size() == tour.size()){
            break;
        }

        // Find the next unused edge incident to the current vertex
        List<E> incident = adjacency.get(currentVertex);
        if(incident == null){
            return null; // invalid structure
        }

        E nextEdge = null;
        for(E e : incident){
            if(!usedEdges.contains(e)){
                nextEdge = e;
                break;
            }
        }

        if(nextEdge == null){
            return null; // incomplete cycle
        }

        usedEdges.add(nextEdge);
        edgeList.add(nextEdge);

        V u = graph.getEdgeSource(nextEdge);
        V v = graph.getEdgeTarget(nextEdge);
        V nextVertex = u.equals(currentVertex) ? v : u;

        vertexList.add(nextVertex);
        currentVertex = nextVertex;
    }

    // Calculate total weight
    double weight = 0.0;
    for(E e : edgeList){
        weight += graph.getEdgeWeight(e);
    }

    return new DefaultGraphPath<>(graph, vertexList, edgeList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()){
        return new org.jgrapht.graph.DefaultGraphPath<>(graph, null, null,
                java.util.Collections.emptyList(), java.util.Collections.emptyList(), 0.0);
    }
    java.util.Map<V, java.util.List<E>> adjacency = new java.util.HashMap<>();
    java.util.Map<V, Integer> degree = new java.util.HashMap<>();
    for (E e : tour){
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(source, k -> new java.util.ArrayList<>()).add(e);
        adjacency.computeIfAbsent(target, k -> new java.util.ArrayList<>()).add(e);
        degree.put(source, degree.getOrDefault(source, 0) + 1);
        degree.put(target, degree.getOrDefault(target, 0) + 1);
    }
    V start = null;
    for (java.util.Map.Entry<V,Integer> entry : degree.entrySet()){
        if (entry.getValue() == 1){
            start = entry.getKey();
            break;
        }
    }
    if (start == null){
        start = adjacency.keySet().iterator().next();
    }
    java.util.List<V> vertices = new java.util.ArrayList<>();
    java.util.List<E> edges = new java.util.ArrayList<>();
    java.util.Set<E> visited = new java.util.HashSet<>();
    V current = start;
    vertices.add(current);
    while (visited.size() < tour.size()){
        java.util.List<E> candidates = adjacency.getOrDefault(current, java.util.Collections.emptyList());
        E nextEdge = null;
        for (E e : candidates){
            if (!visited.contains(e)){
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null){
            break;
        }
        visited.add(nextEdge);
        edges.add(nextEdge);
        V source = graph.getEdgeSource(nextEdge);
        V target = graph.getEdgeTarget(nextEdge);
        V nextVertex = source.equals(current) ? target : source;
        vertices.add(nextVertex);
        current = nextVertex;
    }
    double weight = 0.0;
    for (E e : edges){
        weight += graph.getEdgeWeight(e);
    }
    V targetVertex = vertices.isEmpty() ? null : vertices.get(vertices.size() - 1);
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, start, targetVertex, vertices, edges, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour==null || tour.isEmpty()){
        return null;
    }
    // Build adjacency map
    Map<V,List<E>> adj = new HashMap<>();
    for (E e : tour){
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adj.computeIfAbsent(u,k->new ArrayList<E>()).add(e);
        adj.computeIfAbsent(v,k->new ArrayList<E>()).add(e);
    }
    // Pick a start vertex
    V start = adj.keySet().iterator().next();
    Set<E> visited = new HashSet<>();
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    double totalWeight = 0.0;
    V current = start;
    while (true){
        vertices.add(current);
        E nextEdge = null;
        for (E e : adj.getOrDefault(current, new ArrayList<E>())){
            if (!visited.contains(e)){
                nextEdge = e;
                break;
            }
        }
        if (nextEdge==null){
            break;
        }
        edges.add(nextEdge);
        visited.add(nextEdge);
        totalWeight += graph.getEdgeWeight(nextEdge);
        V next = graph.getEdgeSource(nextEdge).equals(current)
                 ? graph.getEdgeTarget(nextEdge)
                 : graph.getEdgeSource(nextEdge);
        current = next;
        if (current.equals(start)){
            vertices.add(start);
            break;
        }
    }
    // Create GraphPath
    return new GraphPath<V,E>() {
        @Override public List<V> getVertexList(){ return vertices; }
        @Override public List<E> getEdgeList(){ return edges; }
        @Override public V getStartVertex(){ return vertices.isEmpty()?null:vertices.get(0); }
        @Override public V getEndVertex(){ return vertices.isEmpty()?null:vertices.get(vertices.size()-1); }
        @Override public double getLength(){ return totalWeight; }
    };
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    java.util.Map<V, java.util.List<E>> adj = new java.util.HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adj.computeIfAbsent(src, k -> new java.util.ArrayList<>()).add(e);
        adj.computeIfAbsent(tgt, k -> new java.util.ArrayList<>()).add(e);
    }

    V startVertex = null;
    for (V v : adj.keySet()) {
        if (!adj.get(v).isEmpty()) {
            startVertex = v;
            break;
        }
    }

    if (startVertex == null) {
        return new org.jgrapht.graph.SimpleGraphPath<>(graph,
                new java.util.ArrayList<>(), new java.util.ArrayList<>());
    }

    java.util.List<V> vertexList = new java.util.ArrayList<>();
    java.util.List<E> edgeList = new java.util.ArrayList<>();
    java.util.Set<E> visitedEdges = new java.util.HashSet<>();

    V current = startVertex;
    while (visitedEdges.size() < tour.size()) {
        java.util.List<E> edges = adj.get(current);
        E nextEdge = null;
        for (E e : edges) {
            if (!visitedEdges.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) break; // deadlock, malformed tour
        visitedEdges.add(nextEdge);
        edgeList.add(nextEdge);
        vertexList.add(current);
        V src = graph.getEdgeSource(nextEdge);
        V tgt = graph.getEdgeTarget(nextEdge);
        current = src.equals(current) ? tgt : src;
    }
    // add last vertex to close the cycle
    vertexList.add(current);

    return new org.jgrapht.graph.SimpleGraphPath<>(graph, vertexList, edgeList);
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    java.util.List<E> edges = new java.util.ArrayList<>(tour);
    if (edges.isEmpty()) {
        return new edu.uci.ics.jung.graph.util.GraphPathImpl<>(graph,
                java.util.Collections.emptyList());
    }
    java.util.List<E> ordered = new java.util.ArrayList<>();
    java.util.Set<E> remaining = new java.util.HashSet<>(edges);
    E first = edges.get(0);
    V current = graph.getEdgeSource(first);
    ordered.add(first);
    remaining.remove(first);
    while (!remaining.isEmpty()) {
        boolean found = false;
        java.util.Iterator<E> it = remaining.iterator();
        while (it.hasNext()) {
            E e = it.next();
            V u = graph.getEdgeSource(e);
            V v = graph.getEdgeTarget(e);
            if (current.equals(u) || current.equals(v)) {
                ordered.add(e);
                current = current.equals(u) ? v : u;
                it.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            break; // tour is incomplete or not a single cycle
        }
    }
    return new edu.uci.ics.jung.graph.util.GraphPathImpl<>(graph, ordered);
}

