int addConstantNameAndType(final String name,final String descriptor){
    // Scan the existing constant pool to avoid duplicates
    for (int i = 0; i < constantPool.size(); i++) {
        Object entry = constantPool.get(i);
        if (entry instanceof CONSTANT_NameAndType_info) {
            CONSTANT_NameAndType_info cnai = (CONSTANT_NameAndType_info) entry;
            if (cnai.getName().equals(name) && cnai.getDescriptor().equals(descriptor)) {
                return i; // entry already exists
            }
        }
    }
    // Create a new CONSTANT_NameAndType_info entry and add it
    CONSTANT_NameAndType_info newEntry = new CONSTANT_NameAndType_info(name, descriptor);
    constantPool.add(newEntry);
    return constantPool.size() - 1; // index of the newly added entry
}

