    int nameIndex = addConstantUtf8(name);
    int descIndex = addConstantUtf8(descriptor);
    index = constantPool.size();
    constantPool.add(new NameAndTypeInfo(nameIndex, descIndex));
    nameAndTypeIndex.put(key, index);
    return index;
}

int addConstantNameAndType(final String name,final String descriptor){
    // Create a unique key for the name and descriptor pair
    String key = name + "#" + descriptor;
    // If the constant pool already contains this entry, return its index
    Integer existingIndex = nameAndTypeMap.get(key);
    if (existingIndex != null) {
        return existingIndex;
    }
    // Create the new constant pool entry
    Constant_NameAndType_info entry = new Constant_NameAndType_info(name, descriptor);
    // The index will be the current size of the constant pool before adding
    int index = constantPool.size();
    // Add the entry to the constant pool
    constantPool.add(entry);
    // Cache the mapping from key to index for quick lookup next time
    nameAndTypeMap.put(key, index);
    return index;
}

int addConstantNameAndType(final String name, final String descriptor){
    // Retrieve or create the UTF8 constants for the name and descriptor
    int nameIndex = addUtf8(name);
    int descriptorIndex = addUtf8(descriptor);

    // Search the constant pool for an existing CONSTANT_NameAndType entry
    for (int i = 0; i < constantPool.size(); i++) {
        Symbol s = constantPool.get(i);
        if (s.type == Symbol.CONSTANT_NameAndType
                && s.attr1 == nameIndex
                && s.attr2 == descriptorIndex) {
            return i; // Return the index of the existing entry
        }
    }

    // If not found, create a new entry and add it to the pool
    Symbol newEntry = new Symbol(Symbol.CONSTANT_NameAndType, nameIndex, descriptorIndex);
    constantPool.add(newEntry);
    return constantPool.size() - 1; // Return index of the newly added entry
}

int addConstantNameAndType(final String name, final String descriptor){
    // Try to find an existing NameAndType_info in the constant pool
    int existingIndex = constantPool.getNameAndTypeIndex(name, descriptor);
    if (existingIndex != -1) {
        return existingIndex;
    }

    // Resolve the UFT8 indexes for the name and descriptor strings first
    int nameIndex = constantPool.getUtf8Index(name);
    if (nameIndex == -1) {
        nameIndex = constantPool.addUtf8(name);
    }

    int descriptorIndex = constantPool.getUtf8Index(descriptor);
    if (descriptorIndex == -1) {
        descriptorIndex = constantPool.addUtf8(descriptor);
    }

    // Add the new NameAndType_info entry using the resolved indexes
    return constantPool.addNameAndType(nameIndex, descriptorIndex);
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    int length = input.length();
    if (length == 0) {
        return "";
    }
    int start = 0;
    int end = length;
    // Remove surrounding quotes if present
    if (length >= 2) {
        char first = input.charAt(0);
        char last = input.charAt(length - 1);
        if ((first == '\"' && last == '\"') || (first == '\'' && last == '\'')) {
            start = 1;
            end = length - 1;
        }
    }
    StringBuilder sb = new StringBuilder();
    int i = start;
    while (i < end) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < end) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'v':
                    sb.append('\u000B'); // vertical tab
                    break;
                case '0':
                    sb.append('\0');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case 'x':
                    // parse two hex digits
                    if (i + 3 < end) {
                        String hex = input.substring(i + 2, i + 4);
                        try {
                            sb.append((char) Integer.parseInt(hex, 16));
                            i += 3;
                            continue;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('x');
                        }
                    } else {
                        sb.append('\\').append('x');
                    }
                    break;
                case 'u':
                    // parse four hex digits
                    if (i + 5 < end) {
                        String hex = input.substring(i + 2, i + 6);
                        try {
                            sb.append((char) Integer.parseInt(hex, 16));
                            i += 5;
                            continue;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('u');
                        }
                    } else {
                        sb.append('\\').append('u');
                    }
                    break;
                default:
                    sb.append(next);
                    break;
            }
            i += 2;
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

