                        sb.append((char) val);
                        i = j - 1;
                        escaped = false;
                        continue;
                    } else {
                        sb.append(c);
                    }
            }
            escaped = false;
        } else {
            if (c == '\\') {
                escaped = true;
            } else {
                sb.append(c);
            }
        }
    }
    // If the string ends with a single backslash, preserve it
    if (escaped) {
        sb.append('\\');
    }
    return sb.toString();
