                    int val = 0;
                    int j = i + 1;
                    while (j < len && hexLen < 2) {
                        char h = input.charAt(j);
                        int digit = Character.digit(h, 16);
                        if (digit == -1) break;
                        val = val * 16 + digit;
                        hexLen++;
                        j++;
                    }
                    if (hexLen > 0) {
                        sb.append((char) val);
                        i = j - 1;
                    } else {
                        sb.append('x');
                    }
                    break;
                default:
                    if (next >= '0' && next <= '7') {
