        zeroBucket = new HashSet<>();
        // Make sure the list has the correct size
        while (bucketsByLabel.size() <= 0) {
            bucketsByLabel.add(new HashSet<>());
        }
        bucketsByLabel.set(0, zeroBucket);
    }
    // Move all vertices to bucket 0 and update labels
    for (Integer v : minBucket) {
        labels.set(v, 0);
        zeroBucket.add(v);
    }
    minBucket.clear();
}

