private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    // Update links around the node
    if (node.prev != null) {
        node.prev.next = node.next;
    } else {
        // Node is the head
        head = node.next;
    }
    if (node.next != null) {
        node.next.prev = node.prev;
    } else {
        // Node is the tail
        tail = node.prev;
    }
    // Null out the removed node's pointers
    node.prev = null;
    node.next = null;
    // Update size
    size--;
    return true;
}

