private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds){
    java.util.ArrayList<Integer> suffix = new java.util.ArrayList<>(bounds.size());
    long total = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--){
        total += bounds.get(i);
        suffix.add((int) total);
    }
    java.util.Collections.reverse(suffix);
    return new Pair<>(suffix, total);
}

