    long runningSum = 0L;
    for (int i = n - 1; i >= 0; i--) {
        int val = bounds.get(i);
        total += val;
        runningSum += val;
        suffix.add(0, (int) runningSum);
    }
    return new Pair<>(suffix, total);
}

