    java.util.Objects.requireNonNull(arr, "array");
    if (from < 0 || from >= arr.length) {
        throw new IndexOutOfBoundsException("from index out of bounds: " + from);
    }
    if (to < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("to index out of bounds: " + to);
    }
    if (from > to) {
        throw new IllegalArgumentException("from index (" + from + ") is greater than to index (" + to + ")");
    }
    int i = from, j = to;
    while (i < j) {
        V tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
        i++;
        j--;
    }
}

