private void moveAllListNodes(DoublyLinkedList<E> list) {
    synchronized (this) {
        synchronized (list) {
            ListNodeImpl<E> first = list.head.getNext();
            if (first == list.tail) {
                return; // other list is empty, nothing to move
            }
            ListNodeImpl<E> last = list.tail.getPrev();

            // Attach the other's nodes to the end of this list
            this.tail.setNext(first);
            first.setPrev(this.tail);
            this.tail = last;

            // Update size counters
            this.size += list.size;

            // Reset the other list to empty
            list.head.setNext(list.tail);
            list.tail.setPrev(list.head);
            list.size = 0;
        }
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list.size == 0) {
        return;
    }
    ListNodeImpl<E> current = list.head;
    while (current != null) {
        ListNodeImpl<E> next = current.next;
        list.removeListNode(current);
        this.addListNode(current);
        current = next;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == this || list.isEmpty()) {
        return;
    }
    // Grab the first and last nodes of the source list
    Node<E> sourceFirst = list.first;
    Node<E> sourceLast = list.last;

    if (this.isEmpty()) {
        // If this list is empty, just adopt the source nodes
        this.first = sourceFirst;
        this.last = sourceLast;
    } else {
        // Link the two lists together
        this.last.next = sourceFirst;
        sourceFirst.prev = this.last;
        this.last = sourceLast;
    }

    // Update the sizes
    this.size += list.size;

    // Clear the source list
    list.first = null;
    list.last = null;
    list.size = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // No action needed if the source list is this list or is empty
    if (this == list || list.size == 0) {
        return;
    }

    // Obtain the first and last real nodes of the source list
    ListNode<E> srcFirst = list.head.next;
    ListNode<E> srcLast  = list.tail.prev;

    // Detach all nodes from the source list
    list.head.next = list.tail;
    list.tail.prev = list.head;
    int movedCount = list.size;
    list.size = 0;

    // Insert the detached segment at the end of this list
    ListNode<E> thisLast = this.tail.prev;
    thisLast.next = srcFirst;
    srcFirst.prev = thisLast;

    srcLast.next = this.tail;
    this.tail.prev = srcLast;

    // Update the size of this list
    this.size += movedCount;
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    // If the source list is null, empty, or the same as this list, nothing to do.
    if (list == null || list == this || list.isEmpty()){
        return;
    }
    // Grab the first node from the source list, remove it, and append it to this list.
    // Repeat until the source list is empty.
    while (!list.isEmpty()){
        ListNodeImpl<E> node = list.getFirst();
        // Remove from the source list
        list.removeListNode(node);
        // Add to this list
        this.addListNode(node);
    }
}

