public final boolean isTemplateVariablePresent(String name){
    if (name == null || name.isEmpty()){
        return false;
    }
    // Check for a declared field with the given name
    try{
        java.lang.reflect.Field f = this.getClass().getDeclaredField(name);
        return true;
    } catch (NoSuchFieldException e){
        // field not found, continue checking methods
    }
    // Prepare a capitalized version for common getter patterns
    String capitalizedName = name.substring(0, 1).toUpperCase() + name.substring(1);
    java.lang.reflect.Method[] methods = this.getClass().getDeclaredMethods();
    for (java.lang.reflect.Method m : methods) {
        String methodName = m.getName();
        if (methodName.equals(name)
                || methodName.equals("get" + capitalizedName)
                || methodName.equals("is" + capitalizedName)) {
            return true;
        }
    }
    return false;
}

