public void putAllWriteable(BeanMap map){
    // Iterate over all property names in the source map.
    for (String prop : map.keySet()) {
        // Only copy if the source property is readable and the destination is writable.
        if (map.isReadable(prop) && this.isWritable(prop)) {
            Object value = map.get(prop);
            this.put(prop, value);
        }
    }
}

public void putAllWriteable(BeanMap map){
    if(map == null){
        return;
    }
    for(Object kObj : map.keySet()){
        if(!(kObj instanceof String)){
            continue;
        }
        String key = (String) kObj;
        try{
            java.beans.PropertyDescriptor pd = map.getDescriptor(key);
            if(pd != null && pd.getReadMethod() != null && pd.getWriteMethod() != null){
                this.put(key, map.get(key));
            }
        }catch(Exception e){
            // ignore any property descriptor or access errors
        }
    }
}

