    for (Object keyObj : map.keySet()) {
        String key = (String) keyObj;
        Object value;
        try {
            // Attempt to read the property value. Read‑only or write‑only properties
            // will throw an exception and be ignored.
            value = map.get(key);
        } catch (Exception e) {
            continue;
        }
        try {
            // Put the value into this map. If the property is write‑only or
            // otherwise cannot be set, the exception is ignored.
            this.put(key, value);
        } catch (Exception e) {
            // ignore write‑only or read‑only destination properties
        }
    }
}

