public ByteVector putInt(final int intValue){
    final int pos = size;
    final int newSize = pos + 4;
    if (newSize > max) {
        int newCap = Math.max(newSize, max << 1);
        byte[] tmp = new byte[newCap];
        System.arraycopy(buffer, 0, tmp, 0, size);
        buffer = tmp;
        max = newCap;
    }
    buffer[pos] = (byte)(intValue >>> 24);
    buffer[pos + 1] = (byte)(intValue >>> 16);
    buffer[pos + 2] = (byte)(intValue >>> 8);
    buffer[pos + 3] = (byte)intValue;
    size = newSize;
    return this;
}

public ByteVector putInt(final int intValue) {
    // Ensure there is enough room for 4 bytes
    if (pos + 4 > buf.length) {
        int newSize = Math.max(pos + 4, buf.length * 2);
        byte[] newBuf = new byte[newSize];
        System.arraycopy(buf, 0, newBuf, 0, pos);
        buf = newBuf;
    }
    // Store the int in big-endian order
    buf[pos++] = (byte) (intValue >>> 24);
    buf[pos++] = (byte) (intValue >>> 16);
    buf[pos++] = (byte) (intValue >>> 8);
    buf[pos++] = (byte) intValue;
    return this;
}

