public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (name == null || nameStart < 0 || nameStart >= name.length()) {
        return;
    }
    String remaining = name.substring(nameStart);
    String[] parts = remaining.trim().split("\\s+");
    for (int i = 0; i < parts.length; i++) {
        if (!parts[i].isEmpty()) {
            buf.append(Character.toUpperCase(parts[i].charAt(0)));
            if (i < parts.length - 1) {
                buf.append('.');
            }
        }
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    // Assume the full name of this object is stored in a field called fullName.
    // The abbreviation consists of the first letter of each package component
    // (separated by '.') and the full name of the last component.
    if (fullName == null) return;
    int len = fullName.length();
    int i = nameStart;
    while (i < len) {
        // Find the next dot or the end of the string
        int dot = fullName.indexOf('.', i);
        if (dot < 0) dot = len;
        if (dot == i) { // consecutive dots or dot at the start
            i++;
            continue;
        }
        if (dot == len) {
            // Last component – keep it in full
            buf.append(fullName.substring(i));
            break;
        } else {
            // Package component – use its first letter
            buf.append(fullName.charAt(i));
            buf.append('.');
            i = dot + 1;
        }
    }
}

public void abbreviate(final int nameStart,final StringBuffer buf){
    int len = buf.length();
    if (nameStart >= len) {
        return;
    }
    StringBuilder abbrev = new StringBuilder();
    int i = nameStart;
    while (i < len) {
        char c = buf.charAt(i);
        if (c == '.') {
            i++;
            if (i < len) {
                abbrev.append(buf.charAt(i));
                // Skip the rest of the current component
                while (i + 1 < len && buf.charAt(i + 1) != '.') {
                    i++;
                }
            }
        } else {
            abbrev.append(c);
        }
        i++;
    }
    buf.replace(nameStart, len, abbrev.toString());
}

