    while (i < len) {
        char c = buf.charAt(i);
        if (Character.isLetterOrDigit(c)) {
            abbreviation.append(Character.toUpperCase(c));
            // Skip the rest of this word
            i++;
            while (i < len && Character.isLetterOrDigit(buf.charAt(i))) {
                i++;
            }
        } else {
            // Move past separators
            i++;
        }
        // Skip any separators before the next word
        while (i < len && !Character.isLetterOrDigit(buf.charAt(i))) {
            i++;
        }
    }

    // Append the abbreviation to the buffer
    if (abbreviation.length() > 0) {
        buf.append(abbreviation);
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Assume there is a field `name` in the containing class.
    if (name == null || name.length() == 0 || nameStart >= name.length()) {
        return;
    }
    StringBuilder abbr = new StringBuilder();
    boolean inWord = false;
    for (int i = nameStart; i < name.length(); i++) {
        char c = name.charAt(i);
        // Define word boundaries: whitespace, hyphen, underscore, slash
        if (Character.isWhitespace(c) || c == '-' || c == '_' || c == '/') {
            inWord = false;
        } else {
            if (!inWord) {
                // Start of a new word: take first letter
                abbr.append(Character.toUpperCase(c));
                inWord = true;
            }
        }
    }
    buf.append(abbr.toString());
}

public static Type resolveBound(TypeVariable<?> typeVariable){
    if (typeVariable == null){
        return Unknown.class;
    }
    java.lang.reflect.Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0){
        return Unknown.class;
    }
    for (java.lang.reflect.Type bound : bounds){
        if (bound instanceof Class<?> ||
            bound instanceof java.lang.reflect.ParameterizedType ||
            bound instanceof java.lang.reflect.GenericArrayType ||
            bound instanceof java.lang.reflect.WildcardType){
            return bound;
        }
    }
    return Unknown.class;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    Class<?> resolved = resolveClass(bounds[0]);
    return resolved != null ? resolved : Unknown.class;
}

private static Class<?> resolveClass(Type type) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof TypeVariable<?>) {
        TypeVariable<?> tv = (TypeVariable<?>) type;
        Type[] tvBounds = tv.getBounds();
        if (tvBounds != null && tvBounds.length > 0) {
            return resolveClass(tvBounds[0]);
        }
    }
    return null;
}

