}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    Type first = bounds[0];
    if (first == Object.class) {
        return Unknown.class;
    }
    return first;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    for (Type bound : bounds) {
        if (bound instanceof Class<?>) {
            return bound;
        }
        if (bound instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) bound).getRawType();
            if (raw instanceof Class<?>) {
                return raw;
            }
        }
        if (bound instanceof WildcardType) {
            Type[] up = ((WildcardType) bound).getUpperBounds();
            if (up.length > 0 && up[0] instanceof Class<?>) {
                return up[0];
            }
        }
    }
    return Unknown.class;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // A null or empty set or a single vertex is trivially a clique
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }

    // Convert the set to a list for indexed access
    List<V> list = new ArrayList<>(vertices);

    // Check every unordered pair of vertices
    for (int i = 0; i < size - 1; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V vj = list.get(j);
            // For directed graphs we must consider both directions
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false;
            }
        }
    }

    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Trivially true for empty or single-vertex sets
    if (vertices.size() <= 1) return true;
    for (V v : vertices) {
        for (V w : vertices) {
            if (!v.equals(w)) {
                // In a complete graph, every distinct pair of vertices must be connected
                if (!graph.containsEdge(v, w)) {
                    return false;
                }
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices == null || vertices.size() <= 1) {
        return true;
