    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();
    for (int i = 0; i < n; i++) {
        V v1 = vertexList.get(i);
        for (int j = i + 1; j < n; j++) {
            V v2 = vertexList.get(j);
            if (graph.getEdge(v1, v2) == null) {
                return false;
            }
        }
    }
    return true;
}

