private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    List<Integer> sorted = new ArrayList<>(keys.size());
    for (K k : keys) {
        sorted.add((Integer) k);
    }
    Collections.sort(sorted);
    for (K k : keys) {
        Integer val = (Integer) k;
        int idx = Collections.binarySearch(sorted, val);
        Integer lb = null;
        if (idx < 0) {
            int insertPos = -idx - 1;
            if (insertPos > 0) {
                lb = sorted.get(insertPos - 1);
            }
        } else {
            if (idx > 0) {
                lb = sorted.get(idx - 1);
            }
        }
        lowerBounds.add(lb);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    int n = keys == null ? 0 : keys.size();
    List<Integer> result = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        result.add(null);
    }
    if (n <= 1) {
        return result;
    }
    List<Integer> indices = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        indices.add(i);
    }
    indices.sort((i, j) -> {
        @SuppressWarnings("unchecked")
        Comparable<? super K> ki = keys.get(i);
        @SuppressWarnings("unchecked")
        Comparable<? super K> kj = keys.get(j);
        if (ki == null) {
            if (kj == null) return 0;
            return -1;
        } else {
            if (kj == null) return 1;
            return ki.compareTo((K) kj);
        }
    });
    int lastDistinctIndex = -1;
    int i = 0;
    while (i < n) {
        int start = i;
        int currentIdx = indices.get(i);
        K currentKey = keys.get(currentIdx);
        // Find end of this group of equal keys
        int j = i + 1;
        while (j < n) {
            K nextKey = keys.get(indices.get(j));
            if (currentKey == null) {
                if (nextKey != null) break;
            } else {
                if (currentKey.equals(nextKey)) {
                    j++;
                } else {
                    break;
                }
            }
        }
        // Set predecessor for all indices in this group
        for (int g = start; g < j; g++) {
            result.set(indices.get(g), lastDistinctIndex);
        }
        // Update lastDistinctIndex to the index of the last element in this group
        lastDistinctIndex = indices.get(j - 1);
        i = j;
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (K key : keys){
        int maxVal = Integer.MIN_VALUE;
        boolean found = false;
        for (K other : keys){
            // Ensure K is Comparable for comparison
            @SuppressWarnings("unchecked")
            Comparable<K> cmp = (Comparable<K>) other;
            if (cmp.compareTo(key) <= 0){
                int val = ((Number) other).intValue();
                if (!found || val > maxVal){
                    maxVal = val;
                    found = true;
                }
            }
        }
        lowerBounds.add(found ? maxVal : null);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        int current = (Integer) keys.get(i);
        int maxLower = Integer.MIN_VALUE;
        for (int j = 0; j < keys.size(); j++) {
            if (i == j) {
                continue;
            }
            int candidate = (Integer) keys.get(j);
            if (candidate < current && candidate > maxLower) {
                maxLower = candidate;
            }
        }
        lowerBounds.add(maxLower);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        Integer current = (Integer) keys.get(i);
        Integer best = null;
        for (int j = 0; j < keys.size(); j++) {
            if (j == i) continue;
            Integer candidate = (Integer) keys.get(j);
            if (candidate < current) {
                if (best == null || candidate > best) {
                    best = candidate;
                }
            }
        }
        result.add(best == null ? -1 : best);
    }
    return result;
}

