public static String applyRelativePath(String path,String relativePath){
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Arguments cannot be null");
    }
    String[] baseParts = path.split("/");
    java.util.List<String> parts = new java.util.ArrayList<>();
    for (String p : baseParts) {
        if (!p.isEmpty()) {
            parts.add(p);
        }
    }
    String[] relParts = relativePath.split("/");
    for (String seg : relParts) {
        if (seg.isEmpty() || seg.equals(".")) {
            continue;
        } else if (seg.equals("..")) {
            if (!parts.isEmpty()) {
                parts.remove(parts.size() - 1);
            }
        } else {
            parts.add(seg);
        }
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < parts.size(); i++) {
        sb.append(parts.get(i));
        if (i < parts.size() - 1) {
            sb.append("/");
        }
    }
    return sb.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    // Treat an absolute relativePath (starting with '/') as a path from root
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    java.util.ArrayList<String> parts = new java.util.ArrayList<>();
    String[] splitPath = path.split("/");
    // Determine the base directory parts: drop the file component if present
    int endIndex = splitPath.length - 1; // ignore possible trailing empty segment
    for (int i = 0; i < endIndex; i++) {
        parts.add(splitPath[i]);
    }

    String[] segs = relativePath.split("/");
    for (String seg : segs) {
        if (seg.isEmpty() || seg.equals(".")) {
            continue;
        } else if (seg.equals("..")) {
            if (parts.size() > 1) { // keep root empty segment
                parts.remove(parts.size() - 1);
            }
        } else {
            parts.add(seg);
        }
    }

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < parts.size(); i++) {
        String s = parts.get(i);
        if (i == 0 && s.isEmpty()) {
            sb.append('/');
            continue;
        }
        if (i > 0 && sb.length() > 0) {
            sb.append('/');
        }
        sb.append(s);
    }
    if (sb.length() == 0) {
        sb.append('/');
    }
    return sb.toString();
}

