    boolean endsWithSlash = path.endsWith("/");

    // Split the base path into components
    String[] baseParts = path.split("/");
    java.util.List<String> stack = new java.util.ArrayList<>();

    // Determine the limit of components to include from base path
    // If the path does not end with a slash, it is assumed to be a file
    // and the last component is omitted (we work relative to the parent directory)
    int limit = baseParts.length;
    if (!endsWithSlash && limit > 0) {
        // If the last component is empty (due to trailing slash), we keep it
        // otherwise we omit it as it represents a file name
        limit = limit - 1;
    }

    // Process base components
    for (int i = 0; i < limit; i++) {
        String part = baseParts[i];
        if (part.isEmpty() || part.equals(".")) {
            continue; // Skip empty and current directory markers
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }

    // Process relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }

    // Build the resulting path
    StringBuilder sb = new StringBuilder();
    if (isAbsolute) {
        sb.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            sb.append("/");
        }
        sb.append(stack.get(i));
    }

    // Handle the case where the result is the root
    if (sb.length() == 0 && isAbsolute) {
        sb.append("/");
    }

    return sb.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    // Split the base path into components, preserving empty tokens
    String[] pathParts = path.split("/", -1);
    java.util.List<String> base = new java.util.ArrayList<>();
    for (String p : pathParts) {
        base.add(p);
    }

    // Determine if the original path ends with a slash
    boolean endsWithSlash = path.endsWith("/");
    if (!base.isEmpty()) {
        int lastIndex = base.size() - 1;
        String last = base.get(lastIndex);
        if (endsWithSlash) {
            // Remove the trailing empty component created by the slash
            if (last.isEmpty()) {
                base.remove(lastIndex);
            }
        } else {
            // Remove the file component
            if (!last.isEmpty()) {
                base.remove(lastIndex);
            }
        }
    }

    // Process the relative path
    String[] relParts = relativePath.split("/", -1);
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue; // No action for empty or current directory
        }
        if (part.equals("..")) {
            // Prevent removing the root slash component
            if (!base.isEmpty()) {
                if (base.size() == 1 && base.get(0).isEmpty()) {
                    // At root, cannot go higher
                    continue;
                }
                base.remove(base.size() - 1);
            }
        } else {
            base.add(part);
        }
    }

    // Construct the resulting path
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < base.size(); i++) {
        String component = base.get(i);
        if (i == 0 && component.isEmpty()) {
            sb.append("/");
        } else {
            if (sb.length() > 0 && sb.charAt(sb.length() - 1) != '/') {
                sb.append("/");
            }
            sb.append(component);
        }
    }
    return sb.toString();
}

public static String applyRelativePath(String path,String relativePath){
    if (path==null || path.isEmpty()){
        return relativePath==null ? null : relativePath;
    }
    if (relativePath==null || relativePath.isEmpty()){
        return path;
    }
    java.nio.file.Path base = java.nio.file.Paths.get(path).getParent();
    if (base==null){
        base = java.nio.file.Paths.get("");
    }
    java.nio.file.Path result = base.resolve(relativePath).normalize();
    return result.toString().replace('\\','/');
}

