    }
    if (nullCount == 0) {
        // The original array is already a String[] (or at least all elements are non-null),
        // so we can safely cast it back to String[].
        return (String[]) array;
    }
    int newLength = array.length - nullCount;
    String[] result = new String[newLength];
    int index = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[index++] = (String) obj;
        }
    }
    return result;
}

