public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();
    if (index < 0 || index > strLen - subLen) {
        return false;
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        throw new NullPointerException("String or substring cannot be null");
    }
    int subLen = substring.length();
    // If substring is empty, match is true for any index within bounds of str (including at end)
    if (subLen == 0) {
        return index >= 0 && index <= str.length();
    }
    // Index must be within bounds so that the substring fits
    if (index < 0 || index + subLen > str.length()) {
        return false;
    }
    return str.subSequence(index, index + subLen).equals(substring);
}

