        }
    }
}

protected void append(LoggingEvent event){
    String message = event.getRenderedMessage();
    // Assume there is a collection 'clients' holding each connected client
    // The client has a method 'write(String)' or 'println(String)' to send data.
    // We iterate over the collection, send the formatted message to each client,
    // and remove any client that fails during transmission.
    synchronized (clients) {
        Iterator<?> it = clients.iterator();
        while (it.hasNext()) {
            Object clientObj = it.next();
            try {
                // Attempt to send the message; using common interfaces
                if (clientObj instanceof java.io.PrintWriter) {
                    java.io.PrintWriter pw = (java.io.PrintWriter) clientObj;
                    pw.println(message);
                    pw.flush();
                } else if (clientObj instanceof java.io.OutputStream) {
                    java.io.OutputStream os = (java.io.OutputStream) clientObj;
                    os.write(message.getBytes(java.nio.charset.StandardCharsets.UTF_8));
                    os.flush();
                } else {
                    // Attempt to invoke a 'write' or 'send' method via reflection
                    java.lang.reflect.Method writeMethod = clientObj.getClass()
                            .getMethod("write", String.class);
                    writeMethod.invoke(clientObj, message);
                }
            } catch (Exception e) {
                // Remove failed client from collection and optionally log the error
                it.remove();
                // logging or rethrow omitted for brevity
            }
        }
    }
}

protected void append(LoggingEvent event){
    if (clients == null || clients.isEmpty()){
        return;
    }
    final String message = event.getMessage() != null ? event.getMessage().toString() : "";
    for (Writer writer : clients) {
        try {
            writer.write(message);
            writer.flush();
        } catch (IOException e) {
            // optionally log the error or remove the writer from the collection
        }
    }
}

protected void append(LoggingEvent event){
    String message = event.getRenderedMessage();
    for (Socket client : connectedClients) {
        try {
            PrintWriter writer = new PrintWriter(client.getOutputStream(), true);
            writer.println(message);
        } catch (Exception e) {
            // handle exception (e.g., log it or remove the client from the list)
        }
    }
}

