private void checkIfPackedField() throws IOException {
    // When the wire type is LENGTH_DELIMITED, the field might be a packed repeated field.
    int wireType = WireFormat.getTagWireType(currentTag);
    if (wireType == WireFormat.WIRETYPE_LENGTH_DELIMITED) {
        FieldDescriptor fd = fieldDescriptorMap.get(fieldNumber);
        if (fd != null && fd.isRepeated() && fd.isPacked()) {
            // We're entering a packed field – update state.
            inPackedField = true;
            // Read the length of the packed data.
            int packedLength = readRawVarint32();
            // Restrict the input stream to this packed block.
            pushLimit(packedLength);
            return;
        }
    }
    // Either not length-delimited or not a packed repeated field.
    inPackedField = false;
}

private void checkIfPackedField() throws IOException {
    // If we are already consuming a packed field, nothing to do.
    if (_isReadingPackedFields) {
        return;
    }
    // A packed repeated field in protobuf is encoded as a single length‑delimited
    // (wire‑type 2) field.  If we encounter such a field for the first time,
    // switch the reader into the packed‑field mode.
    if (_currentWireType == 2) {   // 2 == LENGTH_DELIMITED
        _isReadingPackedFields = true;
    }
}

private void checkIfPackedField() throws IOException {
    // Packed fields are encoded as length‑delimited (wire type 2) in protobuf.
    if (wireType != 2) {
        return;
    }

    // Get the descriptor for the current field number.  The descriptor
    // must indicate that this field is repeated and packed for the
    // following logic to apply.
    FieldDescriptor fd = descriptor.getFieldByNumber(fieldNumber);
    if (fd == null || !fd.isRepeated() || !fd.isPacked()) {
        return;
    }

    // A packed field stores the total length of the packed data first.
    int packedLength = readRawVarint32();

    // Record that we are currently parsing a packed field and limit the
    // subsequent reads to the packed data length.
    this.isReadingPacked = true;
    this.packedFieldBytesRemaining = packedLength;
    this.inputLimit = packedLength;
}

private void checkIfPackedField() throws IOException {
    // In the Protocol Buffers encoding, wire type 2 indicates a length‑delimited field.
    // This is the encoding used for packed repeated fields.
    // The tag is a varint where the lower 3 bits hold the wire type and
    // the upper bits hold the field number.
    if ((lastTag & 0x07) == 2) {
        // If the field number matches this field, we are reading a packed field.
        if ((lastTag >>> 3) == fieldNumber) {
            inPacked = true;
        } else {
            inPacked = false;
        }
    } else {
        inPacked = false;
    }
}

private void checkIfPackedField() throws IOException {
    // A packed repeated primitive field is encoded as a single length‑delimited
    // value (wire type 2).  If the current field is length‑delimited we
    // mark that we are now reading a packed field.  The boolean flag
    // `isReadingPacked` is assumed to be a member of the parsing object.
    if (currentWireType == 2 && !isReadingPacked) {
        isReadingPacked = true;
    }
}

public int readTag() throws IOException {
    try {
        return readRawVarint32();
    } catch (EOFException e) {
        return 0;
    }
}

public int readTag() throws IOException {
    int firstByte = input.read();               // read first byte of varint
    if (firstByte == -1) {
        // End of stream reached; return 0 as required
        return 0;
    }

    // If continuation bit not set, the tag is fully contained in this byte
    if ((firstByte & 0x80) == 0) {
        return firstByte;
    }

    // Decode remaining bytes of the varint
    int tag = firstByte & 0x7F;
    int shift = 7;
    while (shift < 32) {
        int nextByte = input.read();
        if (nextByte == -1) {
            // EOF encountered while reading a tag: return 0 as specified
            return 0;
        }
        tag |= (nextByte & 0x7F) << shift;
        if ((nextByte & 0x80) == 0) {
            // Last byte of the varint
            break;
        }
        shift += 7;
    }
    return tag;
}

