    // `cPosition` is the current byte position we have already downloaded.
    // `cTotalSize` is the expected total size of the content. If it is unknown,
    // the total portion should be represented by the asterisk (*).
    long cPosition = this.currentPosition; // current downloaded position
    long cTotalSize = this.totalSize;      // total number of bytes of the resource

    if (cTotalSize <= 0) {
        // Total size is unknown – use the wildcard form.
        return "bytes " + cPosition + "-/*";
    }

