public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        throw new FileNotFoundException("File does not exist: " + file);
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return result; // nothing to filter
    }

    // Convenience for quick interval checks
    List<long[]> ranges = new ArrayList<>(timeRanges.size());
    for (ProfileAnalyzeTimeRange r : timeRanges) {
        ranges.add(new long[]{r.getStartTime(), r.getEndTime()});
    }

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Skip empty lines or comments
            line = line.trim();
            if (line.isEmpty() || line.startsWith("#")) {
                continue;
            }

            // Assume each line represents a snapshot in a simple comma‑separated format:
            // timestamp,threadId,stackTrace...
            // The actual parsing logic should reflect the real snapshot format.
            String[] parts = line.split(",");
            if (parts.length < 2) {
                continue; // malformed line
            }

            long timestamp;
            try {
                timestamp = Long.parseLong(parts[0].trim());
            } catch (NumberFormatException e) {
                continue; // skip lines with invalid timestamp
            }

            // Check if the timestamp falls into any of the requested ranges
            boolean inRange = false;
            for (long[] r : ranges) {
                if (timestamp >= r[0] && timestamp <= r[1]) {
                    inRange = true;
                    break;
                }
            }
            if (!inRange) {
                continue;
            }

            // Reconstruct a ThreadSnapshot.
            // Assuming a constructor: new ThreadSnapshot(long timestamp, String threadId, String stackTrace)
            String threadId = parts[1].trim();
            String stackTrace = parts.length > 2 ? line.substring(line.indexOf(parts[2])) : "";
            ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, threadId, stackTrace);
            result.add(snapshot);
        }
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
        while (true) {
            Object obj;
            try {
                obj = ois.readObject();
            } catch (EOFException eof) {
                break;
            }
            if (obj instanceof ThreadSnapshot) {
                ThreadSnapshot ts = (ThreadSnapshot) obj;
                long tsTime = ts.getTimestamp();
                for (ProfileAnalyzeTimeRange tr : timeRanges) {
                    if (tsTime >= tr.getStart() && tsTime <= tr.getEnd()) {
                        result.add(ts);
                        break;
                    }
                }
            }
        }
    } catch (ClassNotFoundException e) {
        throw new IOException("Failed to deserialize ThreadSnapshot from file", e);
    }
    return result;
}

